use ruff_diagnostics::{AlwaysFixableViolation, Diagnostic, Edit, Fix};
use ruff_macros::{derive_message_formats, ViolationMetadata};
use ruff_python_ast::{self as ast, Expr, Stmt};
use ruff_python_semantic::{BindingKind, ScopeKind};
use ruff_python_trivia::{BackwardsTokenizer, SimpleTokenKind, SimpleTokenizer};
use ruff_text_size::{Ranged, TextRange};

use crate::checkers::ast::Checker;

/// ## What it does
/// Checks for `for` loops that can be replaced with `yield from` expressions.
///
/// ## Why is this bad?
/// If a `for` loop only contains a `yield` statement, it can be replaced with a
/// `yield from` expression, which is more concise and idiomatic.
///
/// ## Example
/// ```python
/// for x in foo:
///     yield x
/// ```
///
/// Use instead:
/// ```python
/// yield from foo
/// ```
///
/// ## Fix safety
/// This rule's fix is marked as unsafe, as converting a `for` loop to a `yield
/// from` expression can change the behavior of the program in rare cases.
/// For example, if a generator is being sent values via `send`, then rewriting
/// to a `yield from` could lead to an attribute error if the underlying
/// generator does not implement the `send` method.
///
/// In most cases, however, the fix is safe, and such a modification should have
/// no effect on the behavior of the program.
///
/// ## References
/// - [Python documentation: The `yield` statement](https://docs.python.org/3/reference/simple_stmts.html#the-yield-statement)
/// - [PEP 380 – Syntax for Delegating to a Subgenerator](https://peps.python.org/pep-0380/)
#[derive(ViolationMetadata)]
pub(crate) struct YieldInForLoop;

impl AlwaysFixableViolation for YieldInForLoop {
    #[derive_message_formats]
    fn message(&self) -> String {
        "Replace `yield` over `for` loop with `yield from`".to_string()
    }

    fn fix_title(&self) -> String {
        "Replace with `yield from`".to_string()
    }
}

/// UP028
pub(crate) fn yield_in_for_loop(checker: &mut Checker, stmt_for: &ast::StmtFor) {
    {
        let semantic = checker.semantic();
        for scope in semantic.scopes.ancestors(semantic.scope_id) {
            if let ScopeKind::Function(ast::StmtFunctionDef { is_async, .. }) = scope.kind {
                if *is_async {
                    return;
                }
                break;
            }
        }
    }

    let ast::StmtFor {
        target,
        iter,
        body,
        orelse,
        is_async: _,
        range: _,
    } = stmt_for;

    if !orelse.is_empty() {
        return;
    }

    let [body] = body.as_slice() else {
        return;
    };

    let Stmt::Expr(ast::StmtExpr { value, range: _ }) = body else {
        return;
    };
    let Expr::Yield(ast::ExprYield {
        value: Some(yielded),
        range: _,
    }) = value.as_ref()
    else {
        return;
    };

    let mut pending_pairs = vec![(target.as_ref(), yielded.as_ref())];
    let mut same_expr = true;
    while let Some((left, right)) = pending_pairs.pop() {
        match (left, right) {
            (Expr::Name(left_name), Expr::Name(right_name)) => {
                if left_name.id != right_name.id {
                    same_expr = false;
                }
            }
            (Expr::Tuple(left_tuple), Expr::Tuple(right_tuple)) => {
                if left_tuple.len() == right_tuple.len() {
                    for (left_elt, right_elt) in left_tuple.iter().zip(right_tuple.iter()) {
                        pending_pairs.push((left_elt, right_elt));
                    }
                } else {
                    same_expr = false;
                }
            }
            _ => {
                same_expr = false;
            }
        }
        if !same_expr {
            break;
        }
    }
    if !same_expr {
        return;
    }

    let mut collected_names = Vec::new();
    let mut pending_exprs = vec![yielded.as_ref()];
    while let Some(expr) = pending_exprs.pop() {
        if let Some(name) = expr.as_name_expr() {
            collected_names.push(name);
        } else if let Some(tuple) = expr.as_tuple_expr() {
            for element in tuple.iter() {
                pending_exprs.push(element);
            }
        }
    }

    let mut used_outside_yield = false;
    {
        let semantic = checker.semantic();
        let scope = &semantic.scopes[semantic.scope_id];
        for name in &collected_names {
            if !used_outside_yield {
                for binding_id in scope.get_all(name.id.as_str()) {
                    if !used_outside_yield {
                        let binding = &semantic.bindings[binding_id];
                        match &binding.kind {
                            BindingKind::Annotation
                            | BindingKind::Deletion
                            | BindingKind::UnboundException(_) => {}
                            _ => {
                                for reference_id in &binding.references {
                                    used_outside_yield |=
                                        semantic.reference(*reference_id).range() != name.range();
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    if used_outside_yield {
        return;
    }

    let source = checker.locator().contents();
    let comment_ranges = checker.comment_ranges();
    let expr_start = iter.start();
    let expr_end = iter.end();
    let parent_end = stmt_for.end();

    let mut closing_parens = Vec::new();
    let tokenizer = SimpleTokenizer::new(source, TextRange::new(expr_end, parent_end));
    for token in tokenizer.skip_trivia() {
        if token.kind == SimpleTokenKind::RParen {
            closing_parens.push(token);
        } else {
            break;
        }
    }

    let mut opening_parens = Vec::new();
    let tokenizer = BackwardsTokenizer::up_to(expr_start, source, comment_ranges);
    for token in tokenizer.skip_trivia() {
        if token.kind == SimpleTokenKind::LParen {
            opening_parens.push(token);
        } else {
            break;
        }
    }

    let mut slice_range = iter.range();
    let pair_count = closing_parens.len().min(opening_parens.len());
    if pair_count > 0 {
        let mut index = 0;
        while index < pair_count {
            let left = &opening_parens[index];
            let right = &closing_parens[index];
            if left.start() <= expr_start {
                if right.end() >= expr_end {
                    if left.start() < right.end() {
                        slice_range = TextRange::new(left.start(), right.end());
                    }
                }
            }
            index += 1;
        }
    }

    let contents = &source[slice_range];
    let contents = format!("yield from {contents}");
    let mut diagnostic = Diagnostic::new(YieldInForLoop, stmt_for.range());
    diagnostic.set_fix(Fix::unsafe_edit(Edit::range_replacement(
        contents,
        stmt_for.range(),
    )));
    checker.diagnostics.push(diagnostic);
}

